#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>

int main(int argc, char *argv[])
{
    /* ----- argument count check ----- */
    if (argc < 4) {
        puts("NO_INPUT");
        return 0;
    }

    /* ----- parse base ----- */
    char *end;
    long long base = strtoll(argv[1], &end, 10);
    if (end == argv[1] || *end != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* ----- parse exponent ----- */
    long long exp = strtoll(argv[2], &end, 10);
    if (end == argv[2] || *end != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* ----- parse modulus ----- */
    long long mod = strtoll(argv[3], &end, 10);
    if (end == argv[3] || *end != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* ----- validate modulus ----- */
    if (mod < 1) {
        puts("BAD_MODULUS");
        return 0;
    }
    if (mod > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ----- validate exponent ----- */
    if (exp < 0) {
        puts("NEGATIVE_EXPONENT");
        return 0;
    }

    /* ----- modular exponentiation (binary exponentiation) ----- */
    /* make base positive modulo mod */
    base %= mod;
    if (base < 0)
        base += mod;

    long long result = 1 % mod;          /* initialise accumulator */
    while (exp > 0) {
        if (exp & 1LL) {
            __int128 tmp = (__int128)result * (__int128)base;
            result = (long long)(tmp % mod);
        }
        __int128 sq = (__int128)base * (__int128)base;
        base = (long long)(sq % mod);
        exp >>= 1;
    }

    printf("result=%lld\n", result);
    return 0;
}
